package com.example.payment.integrationtest.paymentgateway;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.springframework.test.web.client.match.MockRestRequestMatchers.content;
import static org.springframework.test.web.client.match.MockRestRequestMatchers.jsonPath;
import static org.springframework.test.web.client.match.MockRestRequestMatchers.method;
import static org.springframework.test.web.client.match.MockRestRequestMatchers.requestTo;
import static org.springframework.test.web.client.response.MockRestResponseCreators.withStatus;
import static org.springframework.test.web.client.response.MockRestResponseCreators.withSuccess;

import com.example.payment.domain.AuthorizationOutcome;
import com.example.payment.domain.Money;
import com.example.payment.infrastructure.HttpPaymentGateway;
import java.math.BigDecimal;
import org.junit.jupiter.api.Test;
import org.springframework.http.HttpMethod;
import org.springframework.http.HttpStatus;
import org.springframework.http.MediaType;
import org.springframework.test.web.client.MockRestServiceServer;
import org.springframework.web.client.RestClient;

/**
 * Verifies the wire contract between {@link HttpPaymentGateway} and the payment provider's
 * REST API: what we send on the way out, and how we interpret every answer shape the
 * provider can send back, including an outright refusal.
 */
class HttpPaymentGatewayTest {

    private final RestClient.Builder builder = RestClient.builder().baseUrl("https://provider.example");
    private final MockRestServiceServer server = MockRestServiceServer.bindTo(builder).build();
    private final HttpPaymentGateway gateway = new HttpPaymentGateway(builder.build());

    @Test
    void sends_the_reference_amount_and_currency_as_the_authorization_request() {
        server.expect(requestTo("/v1/authorizations"))
                .andExpect(method(HttpMethod.POST))
                .andExpect(content().contentType(MediaType.APPLICATION_JSON))
                .andExpect(jsonPath("$.reference").value("ORD-7"))
                .andExpect(jsonPath("$.amount").value(12))
                .andExpect(jsonPath("$.currency").value("EUR"))
                .andRespond(withSuccess("{\"status\":\"approved\"}", MediaType.APPLICATION_JSON));

        gateway.authorize("ORD-7", new Money(BigDecimal.valueOf(12), "EUR"));

        server.verify();
    }

    @Test
    void an_approved_status_in_the_response_body_is_read_as_approved() {
        server.expect(requestTo("/v1/authorizations"))
                .andRespond(withSuccess("{\"status\":\"approved\"}", MediaType.APPLICATION_JSON));

        var outcome = gateway.authorize("ORD-7", new Money(BigDecimal.valueOf(12), "EUR"));

        assertThat(outcome).isEqualTo(AuthorizationOutcome.APPROVED);
    }

    @Test
    void a_declined_status_in_the_response_body_is_read_as_declined() {
        server.expect(requestTo("/v1/authorizations"))
                .andRespond(withSuccess("{\"status\":\"declined\"}", MediaType.APPLICATION_JSON));

        var outcome = gateway.authorize("ORD-7", new Money(BigDecimal.valueOf(12), "EUR"));

        assertThat(outcome).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void the_provider_refusing_the_request_outright_with_402_is_read_as_declined() {
        server.expect(requestTo("/v1/authorizations"))
                .andRespond(withStatus(HttpStatus.PAYMENT_REQUIRED));

        var outcome = gateway.authorize("ORD-7", new Money(BigDecimal.valueOf(12), "EUR"));

        assertThat(outcome).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void an_unexpected_error_status_from_the_provider_is_surfaced_as_a_failure() {
        server.expect(requestTo("/v1/authorizations"))
                .andRespond(withStatus(HttpStatus.INTERNAL_SERVER_ERROR));

        assertThatThrownBy(() -> gateway.authorize("ORD-7", new Money(BigDecimal.valueOf(12), "EUR")))
                .isInstanceOf(IllegalStateException.class)
                .hasMessageContaining("500");
    }
}

